// The hidden engine page (lib/engine.tsx): the website's engine modules (Shared/core/src/engine/studio) bundled into one
// page for the phone's WebView. Run after changing them: pnpm engine (writes lib/engine.page.ts).
import { build } from "esbuild";
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";

const out = await build({ entryPoints: ["../../Shared/core/src/engine/studio/host.ts"], bundle: true, format: "iife", target: "chrome90", nodePaths: [resolve("node_modules")], write: false, minify: false, legalComments: "none" });
const js = out.outputFiles[0].text.replace(/<\/script/gi, "<\/script");
const html = `<!doctype html><html><head><meta charset="utf-8"></head><body><script>${js}</script></body></html>`;
writeFileSync("lib/engine.page.ts", `// Generated by scripts/engine-bundle.mjs (pnpm engine): do not edit.\nexport const ENGINE_PAGE = ${JSON.stringify(html)};\n`);
console.log("engine page:", (html.length / 1024).toFixed(0), "KB");
